use coap::client::Client;
use coap::message::Message;
use coap::transport::UdpSocket;
use std::net::SocketAddr;
use std::time::Duration;

pub struct CoapClient {
    socket: UdpSocket,
    server_addr: SocketAddr,
}

impl CoapClient {
    pub fn new(server_addr: SocketAddr) -> Self {
        let socket = UdpSocket::bind("0.0.0.0:5683").expect("Failed to bind socket");
        socket.set_read_timeout(Some(Duration::from_secs(5))).expect("Failed to set read timeout");
        CoapClient { socket, server_addr }
    }

    pub fn send_request(&self, payload: &[u8]) -> Result<Message, coap::Error> {
        let mut message = Message::new();
        message.set_method(coap::Method::POST);
        message.set_payload(payload.to_vec());
        message.set_token(b"1234".to_vec());
        message.set_content_format(coap::ContentFormat::ApplicationJson);
        message.set_max_age(Duration::from_secs(60));

        self.socket.send_to(&message, &self.server_addr)?;
        Ok(self.socket.recv_from()?)
    }
}
